using System;
using System.Collections.Generic;
using System.Linq;
using NAudio.Wave;

namespace LanguageQuiz
{
    class Program
    {
        static void Main(string[] args)
        {
            Console.WriteLine("Welcome to the Language Quiz Game!");

            Dictionary<string, string> vocabulary = new Dictionary<string, string>()
            {
                {"Car", "Auto"},
                {"Apple", "Apfel"},
                {"Good", "Gut"},
                {"Dog", "Hund"},
                {"Tree", "Baum"},
                {"House", "Haus"},
                {"Beautiful", "Schön"},
                {"Cat", "Katze"},
                {"Toilet", "Toilette"},
