            {
                string randomWord = keys[random.Next(keys.Count)];
                string translation = vocabulary[randomWord];

                Console.WriteLine("Question " + (i+1) + ": What is the translation of '" + randomWord + "'?");
                string userAnswer = Console.ReadLine();

                IWavePlayer waveOutDevice = new WaveOutEvent();
                AudioFileReader audioFileReader = new AudioFileReader(randomWord + ".wav");
                waveOutDevice.Init(audioFileReader);
                waveOutDevice.Play();

                Console.WriteLine("Press any key to stop playing the audio...");
                Console.ReadKey();
                waveOutDevice.Stop();

                if (string.Equals(userAnswer, translation, StringComparison.OrdinalIgnoreCase))
                {
                    Console.WriteLine("Correct!");
                    score++;
