                string wordToRecord = Console.ReadLine();

                Console.WriteLine("Press any key to start recording...");
                Console.ReadKey();
                IWaveIn waveInDevice = new WaveInEvent();
                WaveFileWriter recordedAudioWriter = new WaveFileWriter(wordToRecord + "-recorded.wav",
                    waveInDevice.WaveFormat);
                waveInDevice.DataAvailable += (s, a) =>
                {
                    recordedAudioWriter.Write(a.Buffer, 0, a.BytesRecorded);
                };
                waveInDevice.StartRecording();

                Console.WriteLine("Please pronounce the word '" + wordToRecord + "' and press any key to stop recording...");
                Console.ReadKey();
                waveInDevice.StopRecording();
                recordedAudioWriter.Dispose();
                waveInDevice.Dispose();

                Console.WriteLine("Playback the recorded audio? (y/n)");
                string playbackChoice = Console.ReadLine();

                if (playbackChoice == "y")
                {
                    IWavePlayer waveOutDevice = new WaveOutEvent();
                    AudioFileReader audioFileReader = new AudioFileReader(wordToRecord + "-recorded.wav");
                    waveOutDevice.Init(audioFileReader);
                    waveOutDevice.Play();

                    Console.WriteLine("Press any key to stop playing the audio...");
                    Console.ReadKey();
                    waveOutDevice.Stop();
                }
            }
        }
    }
}
```

